// Original metre-scale household props, modelled from supported solid primitives.
// Every model is a passive compound rigid body, including vehicles and appliances.
// Open vessels use separate floors/walls; there is no invisible solid filler.
const C = { cream:'#e4ded2', ink:'#34474c', steel:'#a1adb1', oak:'#b58e63', dark:'#293339', sage:'#83a399', coral:'#cf7865', blue:'#6993af', glass:'#bfd3d8', paper:'#eee9dc', gold:'#bba16b', rubber:'#454e52', leaf:'#557c58' };
const B=(d,p=[0,0,0],color=C.cream,r)=>({shape:'box',d,p,color,...(r?{r}:{})});
const Y=(radius,height,p=[0,0,0],color=C.steel,r)=>({shape:'cylinder',d:[radius,height],p,color,...(r?{r}:{})});
const E=(d,p=[0,0,0],color=C.cream,r)=>({shape:'ellipsoid',d,p,color,...(r?{r}:{})});
const S=(radius,p=[0,0,0],color=C.cream)=>({shape:'sphere',d:[radius],p,color});
const N=(radius,height,p=[0,0,0],color=C.cream,r)=>({shape:'cone',d:[radius,height],p,color,...(r?{r}:{})});
const T=(radius,tube,p=[0,0,0],color=C.steel,r)=>({shape:'torus',d:[radius,tube],p,color,...(r?{r}:{})});
const PI=Math.PI;
function eulerBasis(x,y,z){const pitch=Math.asin(Math.max(-1,Math.min(1,z[0])));return Math.abs(z[0])<.9999999?[Math.atan2(-z[1],z[2]),pitch,Math.atan2(-y[0],x[0])]:[Math.atan2(y[2],y[1]),pitch,0];}
function rod(a,b,r=.012,color=C.steel){const delta=b.map((v,i)=>v-a[i]),length=Math.hypot(...delta),y=delta.map(v=>v/length);let x=Math.abs(y[2])<.95?[y[1],-y[0],0]:[1,0,0];const magnitude=Math.hypot(...x);x=x.map(v=>v/magnitude);const z=[x[1]*y[2]-x[2]*y[1],x[2]*y[0]-x[0]*y[2],x[0]*y[1]-x[1]*y[0]];return Y(r,length,a.map((v,i)=>(v+b[i])/2),color,eulerBasis(x,y,z));}
function arc(radius,start,end,center=[0,0,0],tube=.012,color=C.steel,count=7,plane='xy'){const point=a=>{const s=Math.sin(a)*radius,c=Math.cos(a)*radius;return plane==='yz'?[center[0],center[1]+s,center[2]+c]:plane==='xz'?[center[0]+c,center[1],center[2]+s]:[center[0]+c,center[1]+s,center[2]];};return Array.from({length:count},(_,i)=>rod(point(start+(end-start)*i/count),point(start+(end-start)*(i+1)/count),tube,color));}
function cup(radius,height,wall=.008,color=C.cream,count=10){return[Y(radius,wall,[0,-height/2+wall/2,0],color),...Array.from({length:count},(_,i)=>{const a=i*PI*2/count;return B([2*radius*Math.tan(PI/count)*1.02,height,wall],[(radius-wall/2)*Math.sin(a),0,(radius-wall/2)*Math.cos(a)],color,[0,a,0]);})];}
function openBox(w,h,d,wall=.012,color=C.cream){return[B([w,wall,d],[0,-h/2+wall/2,0],color),...[-1,1].map(s=>B([w,h,wall],[0,0,s*(d-wall)/2],color)),...[-1,1].map(s=>B([wall,h,d],[s*(w-wall)/2,0,0],color))];}
const shifted=(parts,offset)=>parts.map(p=>({...p,p:p.p.map((v,i)=>v+offset[i])}));
const legs=(w,d,height,y,t=.035,color=C.ink)=>[-1,1].flatMap(x=>[-1,1].map(z=>B([t,height,t],[x*w/2,y,z*d/2],color)));
function handle(w,h,p=[0,0,0],r=.012,color=C.ink){const[x,y,z]=p;return[rod([x-w/2,y,z],[x-w/2,y+h,z],r,color),rod([x-w/2,y+h,z],[x+w/2,y+h,z],r,color),rod([x+w/2,y+h,z],[x+w/2,y,z],r,color)];}
function hollowHandle(w,h,p=[0,0,0],r=.012,color=C.ink){return [...handle(w,h,p,r,color),rod([p[0]-w/2,p[1],p[2]],[p[0]+w/2,p[1],p[2]],r,color)];}
const feet=(w,d,y=-.02,r=.018)=>[-1,1].flatMap(x=>[-1,1].map(z=>Y(r,.035,[x*w/2,y,z*d/2],C.rubber)));
const knobs=(count,y,z,spacing=.065)=>Array.from({length:count},(_,i)=>Y(.014,.012,[(i-(count-1)/2)*spacing,y,z],C.ink,[PI/2,0,0]));
function wheel(radius,width,p){return[Y(radius,width,p,C.rubber,[0,0,PI/2]),Y(radius*.48,width+.012,p,C.steel,[0,0,PI/2])];}
function toolHandle(length=.24,r=.02){return[Y(r,length,[0,-length/2,0],C.coral),Y(r*.78,.022,[0,-length-.01,0],C.ink)];}
function frame(w,h,p=[0,0,0],thickness=.035,color=C.oak){const[x,y,z]=p;return[B([w,thickness,thickness],[x,y-h/2,z],color),B([w,thickness,thickness],[x,y+h/2,z],color),B([thickness,h,thickness],[x-w/2,y,z],color),B([thickness,h,thickness],[x+w/2,y,z],color)];}
function poleStand(height=.8,r=.025){return[Y(.22,.04,[0,0,0],C.ink),Y(r,height,[0,height/2,0],C.steel)];}
function flaskProfile(r=.09,h=.22,neck=.025){return[E([r,h*.37,r],[0,-h*.15,0],C.glass),Y(neck,h*.48,[0,h*.35,0],C.glass),T(neck,.006,[0,h*.59,0],C.cream)];}
const entries=[];
function add(id,name,category,family,mat,parts){entries.push({id:'hh-'+id,name,category,family,mat,parts:parts.flat(Infinity)});}

