function partBounds(part){if(!part?.p)throw new Error(`Invalid household primitive: ${JSON.stringify(part)}`);const rows=rotationRows(part.r),lo=[],hi=[];for(let axis=0;axis<3;axis++){const row=rows[axis],origin=part.p[axis];let extent;
 if(part.shape==='sphere'||part.shape==='ellipsoid'){const radii=part.shape==='sphere'?[part.d[0],part.d[0],part.d[0]]:part.d;extent=Math.hypot(...row.map((value,j)=>value*radii[j]));}
 else if(part.shape==='box')extent=row.reduce((sum,value,j)=>sum+Math.abs(value)*part.d[j]/2,0);
 else if(part.shape==='cylinder')extent=Math.abs(row[1])*part.d[1]/2+Math.hypot(row[0],row[2])*part.d[0];
 else if(part.shape==='torus')extent=Math.hypot(row[0],row[2])*part.d[0]+part.d[1];
 else if(part.shape==='cone'){const base=origin-row[1]*part.d[1]/2,radial=Math.hypot(row[0],row[2])*part.d[0],apex=origin+row[1]*part.d[1]/2;lo[axis]=Math.min(base-radial,apex);hi[axis]=Math.max(base+radial,apex);continue;}
 else throw new Error(`Unsupported household shape ${part.shape}`);lo[axis]=origin-extent;hi[axis]=origin+extent;}return{lo,hi};}
