const prepared=entries.map(entry=>{const mass=masses[entry.id.slice(3)];if(!Number.isFinite(mass)||mass<=0)throw new Error(`Missing household mass estimate: ${entry.id}`);const bounds=entry.parts.map(partBounds),lo=[0,1,2].map(i=>Math.min(...bounds.map(b=>b.lo[i]))),hi=[0,1,2].map(i=>Math.max(...bounds.map(b=>b.hi[i]))),center=lo.map((value,i)=>(value+hi[i])/2);return{item:{id:entry.id,name:entry.name,category:entry.category,family:entry.family,mat:entry.mat,material:materialNames[entry.mat],model:'rigid',behavior:'rigid',mass,massEstimated:true,size:hi.map((value,i)=>value-lo[i])},parts:entry.parts.map(part=>({...part,p:part.p.map((value,i)=>value-center[i])}))};});
const models=new Map(prepared.map(model=>[model.item.id,model.parts]));
export const HOUSEHOLD_CATALOG=prepared.map(model=>model.item);
export const HOUSEHOLD_FAMILIES=[...new Set(HOUSEHOLD_CATALOG.map(item=>item.family))];
export function householdParts(id){const parts=models.get(id);return parts?parts.map(part=>({...part,d:[...part.d],p:[...part.p],...(part.r?{r:[...part.r]}:{})})):null;}
